package cn.iocoder.yudao.module.platform.api.tenant;import cn.iocoder.yudao.module.platform.api.tenant.dto.menu.TenantMenuListReqDTO;import cn.iocoder.yudao.module.platform.api.tenant.dto.menu.TenantMenuRespDTO;import java.util.Collection;import java.util.List;/** * 租户菜单API接口 * * @author zhusy * @since 2022/8/5 */public interface TenantMenuApi {    List<TenantMenuRespDTO> getTenantMenuList(TenantMenuListReqDTO reqDTO);    /**     * 获得指定编号的菜单数组，从缓存中     *     * 任一参数为空时，则返回为空     *     * @param menuIds 菜单编号数组     * @param menuTypes 菜单类型数组     * @param menusStatuses 菜单状态数组     * @return 菜单数组     */    List<TenantMenuRespDTO> getMenuListFromCache(Collection<Long> menuIds, Collection<Integer> menuTypes,                                      Collection<Integer> menusStatuses);    /**     * 获得权限对应的菜单数组     *     * @param permission 权限标识     * @return 数组     */    List<TenantMenuRespDTO> getMenuListByPermissionFromCache(String permission);}